150: // PINS: journey-log chronology, as consumed by render.js's #journey-log.
151: // Entries carry the run key (run, hop): top-down, a run completed later
152: // floats wholly above a run completed earlier, and inside a run the entries
153: // sort hop-ascending whatever emission order the trace engine produces —
154: // a 4-hop trace must never read "hop 2/4" above "hop 1/4" (named
155: // counter-example, pinned in test/panel/render.test.js).
156: export function journeyEntryIsBefore(entry, existing) {
157:   return entry.run > existing.run || (entry.run === existing.run && entry.hop < existing.hop);
158: }
159: 
160: // Pure insertion into a sorted journey list (no DOM here): returns the
161: // ordered array with the new entry placed so the run key order holds.
162: export function orderJourneyEntries(entries, entry) {
163:   const ordered = [...entries];
164:   const index = ordered.findIndex((existing) => journeyEntryIsBefore(entry, existing));
165:   if (index === -1) ordered.push(entry);
166:   else ordered.splice(index, 0, entry);
167:   return ordered;
168: }
