```js
// B-5 compare-tray pure contracts (unit-pinned): rows align hop-wise over
// max(hops), the exhausted side reads the em-dash, texts pass through
// verbatim — nothing here mints or rewrites a hop frame.
const COMPARE_DASH = '—';
export function alignCompareRows(left, right) {
  const total = Math.max(left.hops, right.hops);
  return Array.from({ length: total }, (_, i) => ({
    n: i + 1,
    left: left.entries[i]?.text ?? COMPARE_DASH,
    right: right.entries[i]?.text ?? COMPARE_DASH,
  }));
}

// Slot branch: tick-shaped or entry-less runs are ignored (the named
// counter-example — a crowd tick `{ hops: 0 }` never shifts slots); a
// re-push of either stored run id is a no-op; otherwise first-fill A, B,
// then shift A ← old B, B ← new.
export function nextCompareSlots(slots, newRun) {
  const valid = newRun && newRun.hops >= 2 && Array.isArray(newRun.entries) && newRun.entries.length > 0;
  if (!valid || slots.a?.run === newRun.run || slots.b?.run === newRun.run) {
    return { a: slots.a, b: slots.b, changed: false };
  }
  if (!slots.a) return { a: newRun, b: slots.b, changed: true };
  if (!slots.b) return { a: slots.a, b: newRun, changed: true };
  return { a: slots.b, b: newRun, changed: true };
}
```
