```js
// DOCUMENTS: the B-5 compare tray — a JS-built auto-pair diff inside the
// existing .log-card (panel.html sits at its cap; stage6-registry.js
// precedent). It always shows the two most recent completed trace runs,
// hop-aligned, with the exhausted side reading the em-dash; rows are the
// runs' stored journey-entry texts verbatim — this module never mints or
// rewrites a hop frame (DL-1/DL-3). The pure slot/align contracts live in
// model.js (nextCompareSlots / alignCompareRows, unit-pinned); everything
// here is DOM-bound and covered by e2e/compare.spec.js.
import { alignCompareRows, nextCompareSlots } from './model.js';
import { els } from './render.js';

let slots = { a: null, b: null };
let tray = null;
let headline = null;
let rows = null;
let injected = false;

// CHECKS: injection is idempotent and lazy-lookup (stage6-registry.js
// precedent) — called once at panel boot, before any push can arrive.
export function initCompareTray() {
  if (injected) return;
  injected = true;
  const logCard = document.querySelector('.log-card');
  tray = document.createElement('section');
  tray.id = 'compare-tray';
  tray.dataset.testid = 'compare-tray';
  tray.className = 'compare-tray';
  tray.hidden = true; // hidden until a full pair exists (brief hidden-state rule)
  const title = document.createElement('h3');
  title.className = 'compare-title';
  title.textContent = 'Compare last two runs';
  headline = document.createElement('p');
  headline.id = 'compare-headline';
  headline.dataset.testid = 'compare-headline';
  headline.className = 'compare-headline';
  rows = document.createElement('ol');
  rows.id = 'compare-rows';
  rows.dataset.testid = 'compare-rows';
  tray.append(title, headline, rows);
  logCard.append(tray);
}

// The run's own request descriptor from the trace snapshot — trace.js and
// trace-stage6.js both carry `path`, and the stage-6 machine adds `host`
// (the typed path minus its resource path), so the descriptor is
// `host + path` when a host exists, the typed path otherwise. A snapshot
// without a trace falls back to the controls captured at completion.
function labelOf(snapshot) {
  if (snapshot?.trace?.path) {
    return snapshot.trace.host
      ? `${snapshot.trace.host}${snapshot.trace.path}`
      : snapshot.trace.path;
  }
  return `${els.method.value} ${els.urlInput.value}`;
}

// CHECKS: only the stepOneHop completion branch calls this (the same branch
// as relabelJourneyRun) — a crowd tick never does, so the tray holds exactly
// the two most recent completed trace runs.
export function pushCompareRun({ run, snapshot, hops, entries }) {
  if (!tray) initCompareTray();
  const next = nextCompareSlots(slots, { run, label: labelOf(snapshot), hops, entries });
  if (!next.changed) return;
  slots = next;
  renderCompare();
}

export function clearCompare() {
  slots = { a: null, b: null };
  if (tray) renderCompare();
}

function renderCompare() {
  const { a, b } = slots;
  tray.hidden = !(a && b); // hidden/incomplete-state rule: zero or one run → no rows
  headline.textContent = a && b ? `${a.hops} vs ${b.hops} hops · ${a.label} vs ${b.label}` : '';
  rows.replaceChildren(
    ...(a && b ? alignCompareRows(a, b).map(rowOf) : []),
  );
}

// One row per hop index: `n | left frame | right frame`, texts verbatim
// from the stored entries; single-line cells ellipsize with a title
// tooltip carrying the full text (consistent per row).
function rowOf(row) {
  const item = document.createElement('li');
  item.className = 'compare-row';
  const n = document.createElement('span');
  n.className = 'compare-n';
  n.textContent = String(row.n);
  const left = document.createElement('span');
  left.className = 'compare-cell';
  left.textContent = row.left;
  left.title = row.left;
  const right = document.createElement('span');
  right.className = 'compare-cell';
  right.textContent = row.right;
  right.title = row.right;
  item.append(n, left, right);
  return item;
}
```

