// B-5 compare-tray pure contracts (the DOM side lives in compare.js and is
// covered by e2e/compare.spec.js). A run is the push shape
// `{ run, label, hops, entries }` with the entries' texts verbatim.
describe('compare tray alignment and slot branch', () => {
  const runOf = (id, texts) => ({
    run: id,
    label: `/p${id}`,
    hops: texts.length,
    entries: texts.map((text, i) => ({ run: id, hop: i + 1, label: `hop ${i + 1}/${texts.length}`, text })),
  });
  const nine = ['a1', 'a2', 'a3', 'a4', 'a5', 'a6', 'a7', 'a8', 'a9'];
  const six = ['b1', 'b2', 'b3', 'b4', 'b5', 'b6'];

  // Named counter-example (brief Alignment contract): 9-by-6 runs → 9 rows,
  // rows 7–9 right cell reads the em-dash, and nothing drops.
  it('aligns 9-by-6 runs into 9 rows with the exhausted side reading an em-dash', () => {
    const rows = alignCompareRows(runOf(1, nine), runOf(2, six));
    expect(rows).toHaveLength(9);
    expect(rows.map((r) => r.n)).toEqual([1, 2, 3, 4, 5, 6, 7, 8, 9]);
    expect(rows[0]).toEqual({ n: 1, left: 'a1', right: 'b1' });
    expect(rows[5]).toEqual({ n: 6, left: 'a6', right: 'b6' });
    expect(rows.slice(6).map((r) => r.right)).toEqual(['—', '—', '—']);
    expect(rows.slice(6).map((r) => r.left)).toEqual(['a7', 'a8', 'a9']);
  });

  it('aligns two equal-length runs hop for hop', () => {
    const rows = alignCompareRows(runOf(1, six), runOf(2, six));
    expect(rows).toHaveLength(6);
    expect(rows.every((r) => r.left === `a${r.n}`)).toBe(true);
    expect(rows.every((r) => r.right === `b${r.n}`)).toBe(true);
  });

  it('passes entry texts through verbatim and never mutates the entries', () => {
    const left = runOf(1, nine);
    const right = runOf(2, six);
    const beforeLeft = JSON.stringify(left.entries);
    const beforeRight = JSON.stringify(right.entries);
    const rows = alignCompareRows(left, right);
    expect(rows.map((r) => r.left)).toEqual(nine); // byte-identical texts
    expect(rows.map((r) => r.right)).toEqual([...six, '—', '—', '—']);
    expect(JSON.stringify(left.entries)).toBe(beforeLeft);
    expect(JSON.stringify(right.entries)).toBe(beforeRight);
  });

  it('fills slot A first, then B, then shifts A ← old B, B ← new', () => {
    const a = runOf(1, ['a1', 'a2', 'a3', 'a4']);
    const b = runOf(2, ['b1', 'b2', 'b3', 'b4']);
    const c = runOf(3, ['c1', 'c2', 'c3', 'c4']);
    const first = nextCompareSlots({ a: null, b: null }, a);
    expect(first).toEqual({ a, b: null, changed: true });
    const second = nextCompareSlots({ a: first.a, b: null }, b);
    expect(second).toEqual({ a, b, changed: true });
    const third = nextCompareSlots({ a: second.a, b: second.b }, c);
    expect(third).toEqual({ a: b, b: c, changed: true });
  });

  it('a re-push of a stored run id is a no-op — slots unchanged, changed false', () => {
    const a = runOf(1, ['a1', 'a2', 'a3', 'a4']);
    const b = runOf(2, ['b1', 'b2', 'b3', 'b4']);
    // The brief's two-distinct-runs rule: a completed run equal to the
    // current right slot's run id does not duplicate (and neither does the
    // left slot's).
    expect(nextCompareSlots({ a, b }, { ...b, hops: 6 })).toEqual({
      a,
      b,
      changed: false,
    });
    expect(nextCompareSlots({ a, b }, { ...a, hops: 9 })).toEqual({
      a,
      b,
      changed: false,
    });
  });

  // Named counter-example (brief Trace-runs-only contract, the slot-purity
  // pin): a crowd tick — a tick-shaped run `{ hops: 0 }` with no hop
  // entries — is rejected; the rejection rule is hops < 2 or no entries.
  it('a tick-shaped run (hops 0, no entries) never shifts the stored slots', () => {
    const a = runOf(1, ['a1', 'a2', 'a3', 'a4']);
    const b = runOf(2, ['b1', 'b2', 'b3', 'b4']);
    const tickRun = { run: 9, label: 'tick 5', hops: 0, entries: [] };
    expect(nextCompareSlots({ a, b }, tickRun)).toEqual({ a, b, changed: false });
    expect(nextCompareSlots({ a, b: null }, tickRun)).toEqual({ a, b: null, changed: false });
    expect(nextCompareSlots({ a: null, b: null }, tickRun)).toEqual({
      a: null,
      b: null,
      changed: false,
    });
  });
});

